'use client';

/* ============================================================
 * LegalPage = layout for text pages with numbered sections
 * (used by Privacy Policy). Texts are in app/privacy-policy/page.tsx.
 * You normally do NOT edit this file.
 * ============================================================ */
import { useSelector } from 'react-redux';
import { RootState } from '../store/store';
import Header from './Header';
import PageHero from './PageHero';
import Footer from './Footer';

type T = { en: string; ar: string };

export interface LegalData {
  slides: string[];
  hero: { badge: T; title: T; text: T };
  updated: T; // "Last updated ..." line
  sections: { title: T; paragraphs: T[]; bullets?: T[] }[];
}

export default function LegalPage({ data }: { data: LegalData }) {
  const isAr = useSelector((state: RootState) => state.language.lang) === 'AR';
  const L = (t: T) => (isAr ? t.ar : t.en);

  return (
    <main className="min-h-screen bg-gray-50" dir={isAr ? 'rtl' : 'ltr'}>
      <Header />
      <PageHero slides={data.slides} badge={data.hero.badge} title={data.hero.title} text={data.hero.text} />

      <section className="py-14 sm:py-20 bg-white">
        <div className="w-[90%] max-w-4xl mx-auto space-y-10">
          <p className="text-xs font-bold text-[#d9a036] uppercase tracking-widest">{L(data.updated)}</p>

          {data.sections.map((sec, i) => (
            <div key={i} className="space-y-3">
              <h2 className="flex items-center gap-3 text-lg sm:text-xl font-black text-gray-900">
                <span className="w-8 h-8 rounded-full bg-[#d9a036] text-white text-sm font-black flex items-center justify-center shrink-0">{i + 1}</span>
                {L(sec.title)}
              </h2>
              {sec.paragraphs.map((p, j) => (
                <p key={j} className="text-gray-600 text-sm leading-relaxed font-medium">{L(p)}</p>
              ))}
              {sec.bullets && (
                <ul className="space-y-2 ps-1">
                  {sec.bullets.map((b, j) => (
                    <li key={j} className="flex items-start gap-2.5 text-sm text-gray-600 font-medium">
                      <span className="mt-2 w-1.5 h-1.5 rounded-full bg-[#d9a036] shrink-0" />
                      {L(b)}
                    </li>
                  ))}
                </ul>
              )}
            </div>
          ))}
        </div>
      </section>

      <Footer />
    </main>
  );
}
